  let [s,d,evt] = eventOdds_(ODDS[st.lv][0], ODDS[st.lv][1]); if (useLuck) s = Math.min(100 - d, s + 5);
  const tapHit = req.tap === true; if (tapHit) s = Math.min(100 - d, s + TAP_BONUS);   // 직접 두들기기 명중
