    if ((eff === 'jump' && Math.random() < 0.08) || (eff === 'chaos' && Math.random() < 0.2)) { if (st.lv < MAX) { st.lv++; say_(st,out,`✨ ${eff === 'jump' ? '달토끼가 방아를 한 번 더 찧었다' : '혼돈이 날뛰었다'}! 한 번에 두 단계가 올랐습니다.`,'gold'); out.jump = true; } }
