const ACH_BY = {}; ACHS.forEach(a => ACH_BY[a.id] = a);
function winStreak_(st, myLv, foeLv) { st.streak = (st.streak||0) + 1; st.bestStreak = Math.max(st.bestStreak||0, st.streak); if (foeLv - myLv >= 5) st.giant = 1; }
