function markOf_(st) { const a = st && st.badge && ACH_BY[st.badge]; const sm = st && st.smark && st.smark.wk === weekKey_() ? st.smark.mark : ''; return sm + (a ? a.mark : ''); }
function markRow_(r) { try { return markOf_(JSON.parse(r.state || '{}')); } catch (e) { return ''; } }
