  seasonAdd_(W.st, SEASON_PTS.yachaWin, true); seasonAdd_(L.st, SEASON_PTS.yachaLose, false);
  const ybty = bountyOf_(Object.assign({}, L.st, {lv:lLv, line:lLine})); L.st.streak = 0; if (ybty) { W.st.gold += ybty; feed_(`💰 ${W.row.nickname}님이 ${L.row.nickname}님의 연승을 끊고 현상금 ${fmt(ybty)} G를 받았습니다!`); }
