  st.sheath = cur; if (sh) { st.lv = sh.lv; st.line = sh.line; } else { st.lv = 0; st.line = null; }
  if (cur && sh) say_(st, out, `검을 바꿔 들었습니다. 손에 +${st.lv} ${nameOf(st.lv, st.line)}, 검집에 +${cur.lv} ${nameOf(cur.lv, cur.line)}`, 'ok');
  else if (cur) say_(st, out, `+${cur.lv} ${nameOf(cur.lv, cur.line)}을(를) 검집에 넣고 새 부지깽이를 들었습니다. 검집 검은 사냥에 쓸 수 있습니다.`, 'ok');
  else say_(st, out, `검집에서 +${st.lv} ${nameOf(st.lv, st.line)}을(를) 꺼냈습니다.`, 'ok');
