function sheathSell_(st, req, out, row) {
  const sh = st.sheath; if (!sh || !(sh.lv > 0)) return '검집이 비어 있습니다';
  const p = sellOf(sh.lv, sh.line); st.gold += p; st.sold++; st.sheath = null;
  say_(st, out, `검집의 +${sh.lv} ${nameOf(sh.lv, sh.line)}을(를) ${fmt(p)} G에 팔았습니다.`, 'gold'); out.fx = 'sell';
  if (sh.lv >= 10) feed_(`${row.nickname}님이 +${sh.lv} ${nameOf(sh.lv, sh.line)}을(를) ${fmt(p)} G에 팔았습니다.`);
}

// ── 사냥 무기: 손에 든 검 / 검집 검 / 자동(사냥 효율이 가장 좋은 쪽) ──
const MASTERY_STEP_H = 2, MASTERY_MAX = 20;   // 같은 층 2시간마다 +2%, 최대 +20%
function masteryPct_(st, d) { const ms = ((st.mast||{})[d]) || 0; return Math.min(MASTERY_MAX, Math.floor(ms / (MASTERY_STEP_H * 3600000)) * 2); }
