function weapons_(st) { const a = []; if (st.lv > 0 && st.line != null) a.push({src:'cur', lv:st.lv, line:st.line}); if (st.sheath && st.sheath.lv > 0) a.push({src:'sheath', lv:st.sheath.lv, line:st.sheath.line}); return a; }
function huntWeapon_(st) {
  const h = hunt_(st), ws = weapons_(st); if (!ws.length) return null;
  const pick = h.w === 'cur' || h.w === 'sheath' ? ws.find(x => x.src === h.w) : null; if (pick) return pick;
  const score = x => { const d = h.d >= 0 && x.lv >= huntReq(h.d) ? h.d : bestDungeon_(x.lv); return d < 0 ? 0 : huntGph(d) * huntMult_(st, d, x) + (effOf(x.line) === 'material' ? 1 : 0); };
  return ws.slice().sort((a, b) => score(b) - score(a) || b.lv - a.lv)[0];
}
const huntLv_ = st => { const w = huntWeapon_(st); return w ? w.lv : 0; };
function huntGphFor_(st, d) { return d < 0 ? 0 : Math.round(huntGph(d) * huntMult_(st, d, huntWeapon_(st))); }
function huntWeaponSet_(st, req, out) {
  const w = ['auto','cur','sheath'].indexOf(req.w) >= 0 ? req.w : 'auto', h = hunt_(st);
  if (w === 'sheath' && !(st.sheath && st.sheath.lv > 0)) return '검집이 비어 있습니다';
  if (w === 'cur' && !(st.lv > 0)) return '손에 든 검이 +0입니다';
  h.w = w; const x = huntWeapon_(st);
  say_(st, out, w === 'auto' ? `사냥 무기를 자동으로 고릅니다${x ? ` (지금: +${x.lv} ${nameOf(x.lv, x.line)})` : ''}` : `사냥 무기: +${x.lv} ${nameOf(x.lv, x.line)}`, '');
}

// ── 사냥 재료 ──
const MATS = [
  {k:'iron',  n:'철광석',   icon:'🪨', use:'강화 성공 +2%p'},
  {k:'mana',  n:'마력석',   icon:'🔷', use:'강화 성공 +4%p'},
  {k:'scale', n:'용의 비늘', icon:'🐉', use:'이번 강화에서 파괴가 나오면 유지 (+15 이상에도 쓸 수 있음)'},
  {k:'core',  n:'보스의 핵', icon:'🔶', use:'강화 성공 +8%p'}];
const MAT_BY = {}; MATS.forEach(m => MAT_BY[m.k] = m);
const MAT_BONUS = {iron:2, mana:4, core:8};
function floorMat_(d) { return d <= 3 ? 'iron' : d <= 6 ? 'mana' : 'scale'; }
const MAT_P = [0.5, 0.5, 0.45, 0.45, 0.35, 0.35, 0.3, 0.2, 0.2, 0.2];   // 10분마다 재료가 나올 확률 (층별)
function addMat_(st, k, n) { st.mats = st.mats || {}; st.mats[k] = (st.mats[k] || 0) + n; }

// ── 층 보스: 하루 3번 도전 ──
const BOSS_PER_DAY = 3;
const BOSSES = ['조약돌 골렘','이끼 바위 트롤','화강암 거인','현무암 가고일','흑요석 기사','수정 골렘','용암 드레이크','운석 괴수','미스릴 골렘 왕','별의 수호자'];
const bossLv = d => huntReq(d) + 3;
function huntBoss_(st, req, out) {
  const d = Math.floor(+req.d), w = huntWeapon_(st), dl = daily_(st);
  if (!(d >= 0 && d < DUNGEONS.length)) return '없는 층입니다';
  if (!w) return '보스와 싸울 검이 없습니다';
  if (w.lv < huntReq(d)) return `${d+1}층 보스는 +${huntReq(d)} 이상 검으로 도전할 수 있습니다`;
  if ((dl.boss||0) >= BOSS_PER_DAY) return `보스는 하루 ${BOSS_PER_DAY}번까지 도전할 수 있습니다`;
  dl.boss = (dl.boss||0) + 1;
  const p = winP(w.lv + gradeBonus(w.line), bossLv(d)), win = Math.random() < p, name = BOSSES[d];
  out.boss = {win, d, name, lv:bossLv(d), p:Math.round(p*100), me:{lv:w.lv, line:w.line, name:nameOf(w.lv, w.line)}};
  if (win) {
    const mul = effOf(w.line) === 'material' ? 2 : 1, mk = floorMat_(d), g = huntGph(d) * 2;
    addMat_(st, 'core', 1); addMat_(st, mk, 3 * mul); st.gold += g; st.bossWins = (st.bossWins||0) + 1;
    out.boss.reward = {gold:g, core:1, mat:mk, n:3*mul};
    say_(st, out, `👑 ${d+1}층 보스 「${name}」을(를) 쓰러뜨렸습니다! ${fmt(g)} G, 보스의 핵 1개, ${MAT_BY[mk].n} ${3*mul}개를 얻었습니다.`, 'gold'); out.fx = 'win';
    if (d >= 6) feed_(`${row_nick_(out)}님이 ${d+1}층 보스 「${name}」을(를) 쓰러뜨렸습니다!`);
  } else { say_(st, out, `${d+1}층 보스 「${name}」에게 졌습니다. (오늘 남은 도전 ${BOSS_PER_DAY - dl.boss}번)`, 'bad'); out.fx = 'lose'; }
}
function row_nick_(out) { return (HCTX && HCTX.actorNick) || '누군가'; }

// ── 결투장 주간 시즌 · 현상금 ──
const SEASON_REWARD = [3000000, 1500000, 700000], SEASON_MARK = ['🥇','🥈','🥉'];
const SEASON_PTS = {win:3, lose:1, yachaWin:5, yachaLose:1};
function weekKey_(t) {   // 한국 시간 월요일 날짜
  const d = new Date((t || Date.now()) + 9 * 3600000), dow = (d.getUTCDay() + 6) % 7;
  d.setUTCDate(d.getUTCDate() - dow); return d.toISOString().slice(0, 10);
}
function seasonOf_(st) { const wk = weekKey_(); if (!st.season || st.season.wk !== wk) st.season = {wk, pts:0, w:0}; return st.season; }
function seasonAdd_(st, pts, win) { const s = seasonOf_(st); s.pts += pts; if (win) s.w++; }
function bountyOf_(st) { const k = st.streak || 0; return k >= 3 && st.lv > 0 ? Math.round(prize(st.lv) * (k - 2)) : 0; }
function seasonSettle_() {   // 새 주가 시작된 뒤 첫 요청에서 지난주 1~3등에게 보상
  const wk = weekKey_(), done = settings_().season_done || '';
  if (done === wk) return;
  setSetting_('season_done', wk, '결투장 시즌 정산이 끝난 주 (월요일 날짜)');
  const prev = weekKey_(Date.now() - 7 * 86400000);
  if (!done) return;   // 처음 켜진 주는 정산할 지난주가 없음
  const rows = allRows_().filter(r => r.status === 'ok').map(r => { let s = {}; try { s = JSON.parse(r.state || '{}'); } catch (e) {} return {r, s}; })
    .filter(x => x.s.season && x.s.season.wk === prev && x.s.season.pts > 0).sort((a, b) => b.s.season.pts - a.s.season.pts || b.s.season.w - a.s.season.w).slice(0, 3);
  rows.forEach((x, i) => {
    const st = migrate_(Object.assign(fresh_(), x.s)); st.gold += SEASON_REWARD[i]; st.smark = {mark:SEASON_MARK[i], wk};
    say_(st, null, `${SEASON_MARK[i]} 지난주 결투장 시즌 ${i+1}등! 보상 ${fmt(SEASON_REWARD[i])} G와 이번 주 한정 ${SEASON_MARK[i]} 마크를 받았습니다.`, 'gold');
    HCTX = {act:'season', actorId:'', actorNick:'시즌 정산'}; save_(x.r, st);
  });
  if (rows.length) { const t = `🏆 결투장 주간 시즌 결과: ${rows.map((x, i) => `${SEASON_MARK[i]} ${x.r.nickname}(${x.s.season.pts}점)`).join(' · ')}`; feed_(t); try { chatPush_({sys:true, nick:'대장간', text:t}); } catch (e) {} }
  HCTX = null;
}
function seasonBoard_(rows) {
  const wk = weekKey_();
  return rows.map(r => { let s = {}; try { s = JSON.parse(r.state || '{}'); } catch (e) {} return {id:r.id, nickname:r.nickname, mark:markRow_(r), pts:s.season && s.season.wk === wk ? s.season.pts : 0, w:s.season && s.season.wk === wk ? s.season.w : 0}; })
    .filter(x => x.pts > 0).sort((a, b) => b.pts - a.pts || b.w - a.w).slice(0, 20);
}

// ── 러시안 강화: 한 자루의 검을 돌아가며 강화. 파괴시킨 사람이 탈락 ──
// mode 'last' = 끝까지 살아남은 1명이 판돈 전부 · 'first' = 처음 파괴시킨 1명만 빼고 나머지가 판돈을 나눔
const RR_START = 5, RR_TURN_MS = 20000, RR_MAX = 6, RR_MIN_BET = 1000, RR_WAIT_MS = 10 * 60000;
function rrAll_() { const v = CacheService.getScriptCache().get('rr'); return v ? JSON.parse(v) : {}; }
function rrSave_(m) { CacheService.getScriptCache().put('rr', JSON.stringify(m), 21600); }
function rrPub_(r) { return {id:r.id, mode:r.mode, bet:r.bet, max:r.max, host:r.host, status:r.status, players:r.players, lv:r.lv, turn:r.turn, turnExp:r.turnExp, pot:r.bet * r.players.length, log:r.log.slice(-12), result:r.result || null, created:r.created, round:r.round || 1}; }
function rrPush_(r) { livePush_({type:'rr', room:rrPub_(r)}); }
let RR_ACTOR = null;
function rrPay_(id, amt, text) {   // 다른 사람 지갑에 넣기 (지금 요청한 사람이 아니면 상태를 불러와 저장)
  if (RR_ACTOR && RR_ACTOR.id === id) { RR_ACTOR.st.gold += amt; say_(RR_ACTOR.st, RR_ACTOR.out, text, amt > 0 ? 'gold' : ''); return; }
  const p = findBy_('id', id); if (!p) return;
  const st = migrate_(Object.assign(fresh_(), JSON.parse(p.state || '{}'))); st.gold += amt; say_(st, null, text, amt > 0 ? 'gold' : '');
  HCTX = {act:'rr', actorId:'', actorNick:'러시안 강화'}; save_(p, st);
}
function rrLog_(r, text, kind) { r.log.push({t:Date.now(), text, kind:kind||''}); if (r.log.length > 40) r.log = r.log.slice(-40); }
function rrAlive_(r) { return r.players.filter(p => p.alive); }
function rrNextTurn_(r) {
  const n = r.players.length; let i = r.turn;
  for (let k = 0; k < n; k++) { i = (i + 1) % n; if (r.players[i].alive) { r.turn = i; r.turnExp = Date.now() + RR_TURN_MS; return; } }
}
function rrFinish_(r, winners, loserIds) {
  const pot = r.bet * r.players.length, each = Math.floor(pot / winners.length);
  r.status = 'done'; r.result = {winners:winners.map(p => p.nick), losers:r.players.filter(p => loserIds.indexOf(p.id) >= 0).map(p => p.nick), each, pot};
  winners.forEach(p => rrPay_(p.id, each, `🎰 러시안 강화 승리! ${fmt(each)} G를 받았습니다. (판돈 ${fmt(pot)} G)`));
  rrLog_(r, `🏁 게임 끝! ${winners.map(p => p.nick).join(', ')}님이 ${fmt(each)} G씩 가져갑니다.`, 'gold');
  feed_(`🎰 러시안 강화: ${winners.map(p => p.nick).join(', ')}님이 판돈 ${fmt(pot)} G를 ${winners.length > 1 ? '나눠 가졌습니다' : '차지했습니다'}.`);
}
// 한 번 누르기 (당사자 또는 시간 초과 때 서버가 대신)
function rrPressAs_(r, auto) {
  const p = r.players[r.turn]; if (!p || !p.alive) return;
  const lv = r.lv, [s, d] = ODDS[Math.min(lv, 19)], x = Math.random() * 100, who = p.nick + (auto ? ' (시간 초과)' : '');
  if (x < s) { r.lv = Math.min(19, lv + 1); rrLog_(r, `${who} → 성공! 검이 +${r.lv}이 되었습니다. (다음 파괴 확률 ${ODDS[r.lv][1]}%)`, 'ok'); r.last = {who:p.nick, res:'success', lv:r.lv}; rrNextTurn_(r); return; }
  if (x >= s + d) { rrLog_(r, `${who} → 유지. +${lv} 그대로.`, ''); r.last = {who:p.nick, res:'keep', lv}; rrNextTurn_(r); return; }
  // 파괴
  p.alive = false; r.last = {who:p.nick, res:'destroy', lv};
  rrLog_(r, `💥 ${who} → +${lv} 검이 파괴되었습니다! ${p.nick}님 탈락.`, 'bad');
  if (r.mode === 'first') { rrFinish_(r, r.players.filter(q => q.alive), [p.id]); return; }
  const alive = rrAlive_(r);
  if (alive.length <= 1) { rrFinish_(r, alive, r.players.filter(q => !q.alive).map(q => q.id)); return; }
  r.lv = RR_START; r.round = (r.round || 1) + 1; rrLog_(r, `새 검을 꺼냈습니다. +${RR_START}부터 다시. 남은 사람 ${alive.length}명`, '');
  rrNextTurn_(r);
}
function rrTick_(m) {   // 시간이 지난 차례는 대신 누르고, 오래 기다린 방은 정리
  let changed = false; const now = Date.now();
  Object.keys(m).forEach(id => { const r = m[id];
    if (r.status === 'play') { let guard = 0; while (r.status === 'play' && r.turnExp < now && guard++ < 10) { rrPressAs_(r, true); changed = true; } if (changed) rrPush_(r); }
    else if (r.status === 'wait' && now - r.created > RR_WAIT_MS) { r.players.forEach(p => rrPay_(p.id, r.bet, `러시안 강화 방이 오래 시작되지 않아 판돈 ${fmt(r.bet)} G를 돌려받았습니다.`)); r.status = 'gone'; rrPush_(r); delete m[id]; changed = true; }
    else if ((r.status === 'done' || r.status === 'gone') && now - (r.turnExp || r.created) > 5 * 60000) { delete m[id]; changed = true; } });
  return changed;
}
function rr_(st, req, out, row) {
  const m = rrAll_(); if (rrTick_(m)) rrSave_(m);
  const a = req.op, id = String(req.id || ''), r = m[id];
  const me = {id:row.id, nick:row.nickname, mark:markOf_(st), alive:true};
  const inRoom = Object.values(m).find(x => (x.status === 'wait' || x.status === 'play') && x.players.some(p => p.id === row.id));
  if (a === 'list') { out.rr = Object.values(m).filter(x => x.status !== 'gone').map(rrPub_); return null; }
  if (a === 'create') {
    if (inRoom) return '이미 참가한 방이 있습니다';
    const bet = Math.floor(+req.bet), mode = req.mode === 'first' ? 'first' : 'last', max = Math.max(2, Math.min(RR_MAX, Math.floor(+req.max) || 4));
    if (!(bet >= RR_MIN_BET)) return `판돈은 ${fmt(RR_MIN_BET)} G 이상이어야 합니다`;
    if (st.gold < bet) return '골드가 부족합니다';
    st.gold -= bet; const nid = Utilities.getUuid().slice(0, 6);
    const nr = {id:nid, mode, bet, max, host:row.id, status:'wait', players:[me], lv:RR_START, turn:0, turnExp:0, log:[], created:Date.now(), round:1};
    rrLog_(nr, `${row.nickname}님이 방을 만들었습니다. 판돈 ${fmt(bet)} G · ${mode === 'last' ? '최후의 1인' : '첫 탈락자만 패배'}`, '');
    m[nid] = nr; rrSave_(m); rrPush_(nr); out.rr = [rrPub_(nr)];
    say_(st, out, `🎰 러시안 강화 방을 만들고 판돈 ${fmt(bet)} G를 걸었습니다.`, '');
    try { chatPush_({sys:true, nick:'대장간', text:`🎰 ${row.nickname}님이 러시안 강화 방을 열었습니다! 판돈 ${fmt(bet)} G · ${mode === 'last' ? '최후의 1인' : '첫 탈락자만 패배'} 모드`}); } catch (e) {}
    return null;
  }
  if (!r) return '방을 찾을 수 없습니다';
  if (a === 'join') {
    if (inRoom) return inRoom.id === id ? '이미 이 방에 있습니다' : '이미 다른 방에 참가했습니다';
    if (r.status !== 'wait') return '이미 시작한 방입니다';
    if (r.players.length >= r.max) return '방이 가득 찼습니다';
    if (st.gold < r.bet) return `판돈 ${fmt(r.bet)} G가 부족합니다`;
    st.gold -= r.bet; r.players.push(me); rrLog_(r, `${row.nickname}님이 들어왔습니다. (${r.players.length}/${r.max})`, '');
    say_(st, out, `🎰 러시안 강화 방에 들어가며 판돈 ${fmt(r.bet)} G를 걸었습니다.`, '');
  } else if (a === 'leave') {
    const i = r.players.findIndex(p => p.id === row.id); if (i < 0) return '이 방에 없습니다';
    if (r.status !== 'wait') return '게임 중에는 나갈 수 없습니다';
    if (r.host === row.id) { r.players.forEach(p => p.id === row.id ? null : rrPay_(p.id, r.bet, `방장이 러시안 강화 방을 닫아 판돈 ${fmt(r.bet)} G를 돌려받았습니다.`)); st.gold += r.bet; r.status = 'gone'; rrLog_(r, '방장이 방을 닫았습니다.', ''); say_(st, out, `방을 닫고 판돈 ${fmt(r.bet)} G를 돌려받았습니다.`, ''); }
    else { r.players.splice(i, 1); st.gold += r.bet; rrLog_(r, `${row.nickname}님이 나갔습니다.`, ''); say_(st, out, `방에서 나와 판돈 ${fmt(r.bet)} G를 돌려받았습니다.`, ''); }
  } else if (a === 'start') {
    if (r.host !== row.id) return '방장만 시작할 수 있습니다';
    if (r.status !== 'wait') return '이미 시작했습니다';
    if (r.players.length < 2) return '2명 이상 모여야 시작할 수 있습니다';
    r.status = 'play'; r.lv = RR_START; r.turn = Math.floor(Math.random() * r.players.length); r.turnExp = Date.now() + RR_TURN_MS;
    rrLog_(r, `게임 시작! +${RR_START} 검으로 시작합니다. 첫 차례: ${r.players[r.turn].nick}님`, 'ok');
  } else if (a === 'press') {
    if (r.status !== 'play') return '진행 중인 게임이 아닙니다';
    if (!r.players[r.turn] || r.players[r.turn].id !== row.id) return '내 차례가 아닙니다';
    rrPressAs_(r, false); out.rrLast = r.last;
  } else return '알 수 없는 요청입니다';
  if (r.status === 'gone') delete m[id];
  rrSave_(m); rrPush_(r); out.rr = [rrPub_(r)];
  return null;
}

// ════════════════ Cloudflare 연결부 ════════════════
const CORS = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Methods": "GET, POST, OPTIONS", "Access-Control-Allow-Headers": "Content-Type", "Access-Control-Max-Age": "86400" };
const json = (o, st) => new Response(JSON.stringify(o), { status: st || 200, headers: Object.assign({ "Content-Type": "application/json; charset=utf-8" }, CORS) });

export class Game extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.sql = ctx.storage.sql;
    this.sql.exec("CREATE TABLE IF NOT EXISTS sheets (name TEXT PRIMARY KEY)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS cells (sheet TEXT NOT NULL, r INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY (sheet, r))");
    this.sql.exec("CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL, exp INTEGER NOT NULL)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS hist (id INTEGER PRIMARY KEY AUTOINCREMENT, pid TEXT NOT NULL, t INTEGER NOT NULL, act TEXT, lv0 INTEGER, lv1 INTEGER, line0 INTEGER, line1 INTEGER, gold0 INTEGER, gold1 INTEGER, state TEXT)");
    this.sql.exec("CREATE INDEX IF NOT EXISTS hist_pid_t ON hist (pid, t)");
    // 카톡 자랑 카드: 플레이어마다 최근 1장만 보관 (덮어씀)
    this.sql.exec("CREATE TABLE IF NOT EXISTS share (pid TEXT PRIMARY KEY, v INTEGER, img BLOB, title TEXT, descr TEXT, nick TEXT)");
    // 한 번만: 예전 기록에서 메시지 기록(log)을 빼서 용량을 줄임
    try { const done = this.sql.exec("SELECT v FROM kv WHERE k = '__slim1'").toArray(); if (!done.length) { this.sql.exec("UPDATE hist SET state = json_remove(state, '$.log') WHERE json_valid(state)"); this.sql.exec("INSERT OR REPLACE INTO kv (k, v, exp) VALUES ('__slim1', '1', 9e15)"); } } catch (e) { console.log("slim skip", e && e.message); }
    this.mem = { sql: this.sql, sheets: new Map(), kv: null, kvDirty: new Set(), touched: new Set(), ping: false };
    // 연결 유지 신호는 서버를 깨우지 않고 바로 답합니다 (요금 없음)
    try { ctx.setWebSocketAutoResponse(new WebSocketRequestResponsePair("ping", "pong")); } catch (e) {}
  }
  flush_() {
    const m = this.mem;
    this.ctx.storage.transactionSync(() => {
      m.touched.forEach(sh => sh.flush(this.sql)); m.touched.clear();
      m.kvDirty.forEach(k => { const e = m.kv && m.kv.get(k); if (e) this.sql.exec("INSERT OR REPLACE INTO kv (k, v, exp) VALUES (?, ?, ?)", k, e.v, e.exp); else this.sql.exec("DELETE FROM kv WHERE k = ?", k); });
      m.kvDirty.clear();
    });
  }
  broadcast_() {
    for (const ws of this.ctx.getWebSockets()) { try { ws.send("live"); } catch (e) {} }
  }
  run_(fn) {
    DB = this.mem; this.mem.ping = false;
    try { const out = fn(); this.flush_(); if (this.mem.ping) this.broadcast_(); return out; }
    catch (e) {   // 중간에 실패하면 메모리 사본을 버려 저장된 값과 어긋나지 않게 합니다
      this.mem.sheets.clear(); this.mem.kv = null; this.mem.kvDirty.clear(); this.mem.touched.clear();
      console.log("api error", e && e.stack || e); return { ok: false, error: "서버 오류가 났습니다. 잠시 뒤 다시 시도하세요" };
    }
  }
  async fetch(req) {
    const url = new URL(req.url);
    if (url.pathname === "/ws") {
      if (req.headers.get("Upgrade") !== "websocket") return new Response("websocket only", { status: 426 });
      const pair = new WebSocketPair(); this.ctx.acceptWebSocket(pair[1]);
      return new Response(null, { status: 101, webSocket: pair[0] });
    }
    if (req.method === "GET" && url.pathname.startsWith("/img/")) return this.shareImg_(url);
    if (req.method === "GET" && url.pathname.startsWith("/s/")) return this.sharePage_(url);
    let body = {}; try { body = JSON.parse(await req.text() || "{}"); } catch (e) {}
    if (body.action === "shareSave") return json(this.shareSave_(body, url));
    if (body.action === "__import") return json(this.run_(() => importData_(body)));
    if (["pitrCheck", "pitrRestore", "pitrUndo"].indexOf(body.action) >= 0) return json(await this.pitr_(body));
    if (body.action === "storage") return json(this.storage_(body));
    return json(this.run_(() => api(body.action, body)));
  }
  // ── 서버 전체 되돌리기 (Cloudflare 특정 시점 복구, 최근 30일) ──
  async pitr_(body) {
    const auth = this.run_(() => { const r = findBy_('token', String(body.token || '')); return r && r.role === 'admin' ? {ok:true} : {ok:false, error:'관리자만 할 수 있습니다'}; });
    if (!auth.ok) return auth;
    const S = this.ctx.storage;
    try {
      let bm;
      if (body.action === "pitrCheck") bm = await S.getCurrentBookmark();          // 지금 시점으로 다시 불러오기 (데이터는 그대로)
      else if (body.action === "pitrUndo") { bm = String(body.bookmark || ""); if (!bm) return {ok:false, error:'되돌리기 취소 코드가 없습니다'}; }
      else {
        const t = +body.time, now = Date.now();
        if (!(t > now - 30 * 86400000 + 60000 && t < now - 60000)) return {ok:false, error:'최근 30일 안, 지금보다 1분 이전 시각만 고를 수 있습니다'};
        bm = await S.getBookmarkForTime(t);
      }
      const undo = await S.onNextSessionRestoreBookmark(bm);
      setTimeout(() => { try { this.ctx.abort("restore"); } catch (e) {} }, 300);   // 다시 시작하면서 복구가 적용됨
      return {ok:true, undo, check: body.action === "pitrCheck"};
    } catch (e) {
      return {ok:false, error:'서버 전체 되돌리기를 쓸 수 없습니다: ' + (e && e.message || e)};
    }
  }
  // ── 저장소 상태 (관리자): 전체 크기와 표마다 줄 수 ──
  storage_(body) {
    const auth = this.run_(() => { const r = findBy_('token', String(body.token || '')); return r && r.role === 'admin'; });
    if (auth !== true) return {ok:false, error:'관리자만 볼 수 있습니다'};
    const one = q => { try { return this.sql.exec(q).toArray()[0] || {}; } catch (e) { return {}; } };
    const cells = {}; try { for (const r of this.sql.exec("SELECT sheet, COUNT(*) AS n, SUM(LENGTH(data)) AS b FROM cells GROUP BY sheet")) cells[r.sheet] = {rows:r.n, bytes:r.b}; } catch (e) {}
    const h = one("SELECT COUNT(*) AS n, SUM(LENGTH(state)) AS b, MIN(t) AS t0 FROM hist"), k = one("SELECT COUNT(*) AS n, SUM(LENGTH(v)) AS b FROM kv");
    let size = 0; try { size = this.sql.databaseSize; } catch (e) {}
    return {ok:true, size, hist:{rows:h.n||0, bytes:h.b||0, since:h.t0||0}, kv:{rows:k.n||0, bytes:k.b||0}, cells, sockets:this.ctx.getWebSockets().length, limit:1e9};
  }
  // ── 카톡 공유: 자랑 카드 저장 → 미리보기 카드가 뜨는 공유 주소 ──
  shareSave_(body, url) {
    const who = this.run_(() => { const r = findBy_('token', String(body.token || '')); return r && r.status === 'ok' ? {id:r.id, nick:r.nickname} : null; });
    if (!who || !who.id) return {ok:false, error:'로그인이 필요합니다'};
    const b64 = String(body.img || "").replace(/^data:image\/\w+;base64,/, "");
    if (!b64 || b64.length > 1500000) return {ok:false, error:'자랑 카드가 너무 큽니다'};
    let bytes; try { const bin = atob(b64); bytes = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i); } catch (e) { return {ok:false, error:'자랑 카드를 읽지 못했습니다'}; }
    if (!(bytes[0] === 0xFF && bytes[1] === 0xD8) && !(bytes[0] === 0x89 && bytes[1] === 0x50)) return {ok:false, error:'그림 파일이 아닙니다'};
    const clip = (t, n) => String(t || "").replace(/[\u0000-\u001f]/g, " ").slice(0, n);
    const v = Date.now();
    this.sql.exec("INSERT OR REPLACE INTO share (pid, v, img, title, descr, nick) VALUES (?,?,?,?,?,?)", who.id, v, bytes, clip(body.title, 80), clip(body.desc, 300), who.nick);
    return {ok:true, url:`${url.origin}/s/${who.id}?v=${v}`, img:`${url.origin}/img/${who.id}.jpg?v=${v}`};
  }
  shareRow_(id) { const r = this.sql.exec("SELECT * FROM share WHERE pid = ?", String(id || "")).toArray(); return r[0] || null; }
  shareImg_(url) {
    const id = url.pathname.slice(5).replace(/\.(jpg|png)$/, ""), r = this.shareRow_(id);
    if (!r || !r.img) return new Response("not found", {status:404});
    const b = new Uint8Array(r.img), png = b[0] === 0x89;
    return new Response(b, {headers:{"Content-Type": png ? "image/png" : "image/jpeg", "Cache-Control":"public, max-age=600", "Access-Control-Allow-Origin":"*"}});
  }
  sharePage_(url) {
    const id = url.pathname.slice(3).split("/")[0], r = this.shareRow_(id), GAME = "https://ruddls0814-debug.github.io/sword/";
    const esc = t => String(t || "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
    const title = r ? r.title : "검키우기 대장간", desc = r ? r.descr : "녹슨 부지깽이를 +20 전설의 검으로! 친구들과 함께 강화하고 배틀하세요.";
    const img = r ? `${url.origin}/img/${id}.jpg?v=${r.v}` : GAME + "og.png", go = GAME + (r ? `?from=${encodeURIComponent(r.nick)}` : "");
    const html = `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title><meta property="og:type" content="website"><meta property="og:site_name" content="검키우기 대장간">
<meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(desc)}">
<meta property="og:image" content="${esc(img)}"><meta property="og:image:width" content="900"><meta property="og:image:height" content="1200">
<meta property="og:url" content="${esc(url.href)}"><meta name="twitter:card" content="summary_large_image"><style>body{margin:0;background:#140e0b;color:#f1e6d6;font:16px/1.6 system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;text-align:center;padding:20px}a{display:inline-block;margin-top:14px;background:#ff7a2f;color:#1a0f08;font-weight:800;padding:14px 22px;border-radius:12px;text-decoration:none}img{max-width:min(320px,80vw);border-radius:14px}</style></head>
<body><div><img src="${esc(img)}" alt=""><h1 style="font-size:20px">${esc(title)}</h1><p>${esc(desc)}</p><a href="${esc(go)}">⚔️ 지금 바로 하러 가기</a></div><script>location.replace(${JSON.stringify(go)})</script></body></html>`;
    return new Response(html, {headers:{"Content-Type":"text/html; charset=utf-8", "Cache-Control":"public, max-age=60"}});
  }
  webSocketMessage(ws, msg) { if (msg === "ping") try { ws.send("pong"); } catch (e) {} }
  webSocketClose(ws, code) { try { ws.close(code, "bye"); } catch (e) {} }
  webSocketError(ws) { try { ws.close(1011, "error"); } catch (e) {} }
}

// 구글 시트에서 옮겨 온 데이터를 한 번만 넣습니다 (players 가 비어 있을 때만)
function importData_(body) {
  const p = BOOK.getSheetByName("players");
  if (p && p.getLastRow() > 1) return { ok: false, error: "이미 데이터가 있어 가져오기를 막았습니다" };
  const got = {};
  Object.keys(body.sheets || {}).forEach(name => {
    if (["players", "settings", "rooms", "chat", "feed"].indexOf(name) < 0) return;
    const rows = body.sheets[name] || []; let sh = BOOK.getSheetByName(name) || BOOK.insertSheet(name);
    if (sh.getLastRow()) sh.deleteRows(1, sh.getLastRow());
    rows.forEach(r => sh.appendRow(r.map(v => (typeof v === "string" && /^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?Z$/.test(v) ? new Date(v) : v))));
    got[name] = rows.length;
  });
  CacheService.getScriptCache().remove("settings"); CacheService.getScriptCache().remove("rooms");
  return { ok: true, imported: got };
}

export default {
  async fetch(req, env) {
    if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
    const url = new URL(req.url);
    const stub = env.GAME.get(env.GAME.idFromName("main"));
    if (url.pathname === "/ws") return stub.fetch(req);
    if (req.method === "POST") return stub.fetch(req);
    if (req.method === "GET" && (url.pathname.startsWith("/s/") || url.pathname.startsWith("/img/"))) return stub.fetch(req);
    return json({ ok: true, service: "검키우기 대장간 서버" });
  },
};
